parameters.jsCode:
// Edit the competitor sites to crawl below. Each entry is a *start URL*;
// the crawler follows links within the site up to `maxDepth`, scraping
// every page whose URL matches `includeRegexp`.
//
// IMPORTANT: paste the "Crawl Result Webhook" Production URL into
// CALLBACK_URL before the first scheduled run — that is where ScraperAPI
// streams each scraped page. (Open the webhook node to copy its URL.)
//
// `countryCode` sets the ScraperAPI proxy region (us, gb, de, fr, etc.).
// Tighten `includeRegexp` to a section (e.g. /news, /blog) to control
// credit spend — crawling a whole site with rendering can be expensive.

const CALLBACK_URL = 'https://YOUR-N8N-HOST/webhook/competitor-crawl';

const sites = [
  { startUrl: 'https://www.anthropic.com/news', countryCode: 'us', includeRegexp: 'https://www\\.anthropic\\.com/news.*', maxDepth: 2 },
  { startUrl: 'https://openai.com/blog', countryCode: 'us', includeRegexp: 'https://openai\\.com/(blog|index).*', maxDepth: 2 },
  { startUrl: 'https://blog.google/technology/ai/', countryCode: 'us', includeRegexp: 'https://blog\\.google/technology/ai.*', maxDepth: 2 },
];

return sites.map((s, i) => ({
  json: { ...s, callbackUrl: CALLBACK_URL },
  pairedItem: { item: i },
}));

// ScraperAPI streams one POST per scraped page to this webhook, plus a
// final job-summary POST when the crawl finishes. Keep only successful
// per-page results; drop the summary and any failed fetches.

const payload = $json.body || $json;
const results = Array.isArray(payload) ? payload : [payload];

const out = [];
for (const r of results) {
  const resp = r && r.response;
  const status = resp && resp.statusCode;
  // A page result has a url and a response.body string; the job summary
  // (jobState / completed / failed) and failed fetches are skipped.
  if (!r || !r.url || !resp || typeof resp.body !== 'string') continue;
  if (status && status >= 400) continue;
  out.push({
    json: { url: r.url, body: resp.body, statusCode: status || 200 },
    pairedItem: { item: 0 },
  });
}

return out;

// Clean the markdown body, cap length to keep AI cost predictable,
// and compute a stable hash of the content.

const item = $input.first().json;
const body = (item && item.body) || '';
const url = item && item.url;

const cleaned = String(body)
  .replace(/\u0000/g, '')
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const MAX = 8000;
const content = cleaned.length > MAX ? cleaned.slice(0, MAX) + '\n…(truncated)' : cleaned;

// FNV-1a 32-bit hash — fast, dependency-free, plenty for change detection.
let h = 2166136261;
for (let i = 0; i < content.length; i++) {
  h ^= content.charCodeAt(i);
  h = Math.imul(h, 16777619);
}
const hash = (h >>> 0).toString(16);

return [{
  json: {
    url,
    content,
    hash,
    scraped_at: new Date().toISOString(),
  },
  pairedItem: { item: 0 },
}];

// Combine the current scrape with whatever Retrieve Previous returned.
// First-time URLs have no previous row — store them as a silent baseline
// (no AI, no digest entry) so the digest only ever reports real changes.

const current = $('Limit Content Length').first().json;
const previous = $input.first().json || {};

const hasPrevious = !!previous.last_content_hash;
const hashChanged = hasPrevious && previous.last_content_hash !== current.hash;
const significant = current.content && current.content.length > 200; // skip near-empty pages

return [{
  json: {
    url: current.url,
    current_content: current.content,
    current_hash: current.hash,
    current_seen_at: current.scraped_at,
    previous_content: hasPrevious ? (previous.last_content || '') : '',
    previous_hash: hasPrevious ? previous.last_content_hash : '',
    previous_seen_at: hasPrevious ? (previous.last_seen_at || 'unknown') : 'never',
    first_seen: !hasPrevious,
    changed: hashChanged && significant,
  },
  pairedItem: { item: 0 },
}];

