parameters.jsCode:
// Only rows with a last_summary are material changes recorded today.
const changes = (($input.first().json || {}).changes || [])
  .filter(c => c.last_summary && !String(c.last_summary).toUpperCase().includes('NO_MATERIAL_CHANGE'));

const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// The agent emits one material change per line (optionally prefixed with a
// "- "/"*"/"•" marker). Split into bullet points; fall back to the whole
// summary as a single bullet if it ever arrives as one block.
const toBullets = (summary) => {
  const lines = String(summary == null ? '' : summary)
    .split(/\r?\n+/)
    .map(l => l.replace(/^\s*[-*•]\s*/, '').trim())
    .filter(Boolean);
  return lines.length ? lines : [String(summary == null ? '' : summary).trim()];
};

const today = new Date().toISOString().slice(0, 10);

// Count total individual bullet points across all competitors
const totalBullets = changes.reduce((sum, c) => sum + toBullets(c.last_summary).length, 0);
const subject = `Competitor content update — ${totalBullets} change${totalBullets === 1 ? '' : 's'} on ${today}`;

const rowsHtml = changes.map(c => {
  const items = toBullets(c.last_summary)
    .map(b => `<li style="margin-bottom:4px;line-height:1.5">${esc(b)}</li>`)
    .join('');
  return `<tr>
  <td style="padding:12px;border:1px solid #ddd;vertical-align:top;width:30%">
    <a href="${esc(c.url)}" style="color:#1f6fcc;text-decoration:none;word-break:break-all" target="_blank">${esc(c.url)}</a>
  </td>
  <td style="padding:12px;border:1px solid #ddd;vertical-align:top">
    <ul style="margin:0;padding-left:20px">${items}</ul>
  </td>
</tr>`;
}).join('');

const html = `<div style="font-family:-apple-system,Segoe UI,sans-serif;max-width:1200px">
  <h2 style="margin:0 0 12px">${esc(subject)}</h2>
  <p style="color:#555;margin:0 0 16px">Pages monitored via ScraperAPI. Summaries written by AI on detected changes.</p>
  <table style="width:100%;border-collapse:collapse;border:1px solid #ddd">
    <thead>
      <tr style="background-color:#f5f5f5">
        <th style="padding:12px;border:1px solid #ddd;text-align:left;font-weight:600">URL</th>
        <th style="padding:12px;border:1px solid #ddd;text-align:left;font-weight:600">Changes Detected</th>
      </tr>
    </thead>
    <tbody>${rowsHtml}</tbody>
  </table>
</div>`;

const slackBlocks = JSON.stringify({
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: subject } },
    ...changes.flatMap(c => ([
      { type: 'section', text: { type: 'mrkdwn', text: `*<${c.url}|${c.url}>*\n${toBullets(c.last_summary).map(b => `• ${b}`).join('\n')}` } },
      { type: 'divider' },
    ])),
  ],
});

const text = changes.map(c => `${c.url}\n${toBullets(c.last_summary).map(b => `  • ${b}`).join('\n')}`).join('\n\n');

return [{ json: { count: totalBullets, subject, html, text, slackBlocks } }];
